    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '301: A patient has "S1Q3T3" and a new RBBB on ECG. What is the most likely CXR finding?', '["Bat-wing edema", "Westermark sign or Hampton''s hump (though often normal)", "Water-bottle heart", "Rib notching"]', 1, 'In acute PE, the CXR is often normal, but classic signs like Westermark sign (oligemia) or Hampton''s hump (infarct) can be seen.'),
    (v_topic_id, '302: "Pulmonary Hypertension" is characterized on CXR by:', '["Enlargement of the central pulmonary arteries and pruning of the peripheral vessels", "Large pleural effusions", "Atelectasis", "Normal hila"]', 0, 'High pressure causes central dilation while peripheral vessels may look small or absent.'),
    (v_topic_id, '303: On a LATERAL CXR, if the heart border obscures the lower part of the sternum, this indicates:', '["Left atrial enlargement", "Right ventricular enlargement", "Aortic aneurysm", "Pneumonia"]', 1, 'The right ventricle occupies the retrosternal space.'),
    (v_topic_id, '304: A "double track" or "tram-track" appearance of the bronchi on CXR suggests:', '["Acute bronchitis", "Bronchiectasis", "Pneumonia", "Lung cancer"]', 1, 'Thickened, dilated bronchial walls are seen in profile as parallel lines.'),
    (v_topic_id, '305: "Fleischner Society" guidelines for a sub-centimeter lung nodule in a low-risk patient recommend follow-up at:', '["1 month", "3 months", "6 to 12 months", "No follow-up needed if < 6 mm"]', 3, 'Small nodules (< 6 mm) in low-risk patients generally do not require routine follow-up.'),
    (v_topic_id, '306: In a patient with "Acute Respiratory Distress Syndrome" (ARDS), the infiltrates usually appear:', '["After 1 week", "Within 12 to 48 hours of the inciting event", "Immediately", "Only after death"]', 1, 'The rapid development of diffuse alveolar damage is a key clinical feature of ARDS.'),
    (v_topic_id, '307: "Kerley A lines" are located in the:', '["Lung bases", "Upper lobes, radiating from the hila", "Pleural space", "Costophrenic angles"]', 1, 'Kerley A lines are longer and more central than Kerley B lines.'),
    (v_topic_id, '308: "Kerley C lines" are:', '["Horizontal lines at the base", "Short, fine lines throughout the lungs, representing a reticular pattern of septal thickening", "Calcified ribs", "Tubes"]', 1, 'They are less common than A or B lines.'),
    (v_topic_id, '309: "Atelectasis" of the "Left Upper Lobe" (LUL) shows which classic sign on a lateral film?', '["The Luftsichel sign", "The anterior displacement of the major fissure parallel to the sternum", "The spine sign", "Flat diaphragm"]', 1, 'The major fissure is pulled forward as the LUL collapses anteriorly.'),
    (v_topic_id, '310: The "Luftsichel" sign (air crescent around the aortic knob) is seen in:', '["Right upper lobe collapse", "Left upper lobe collapse", "Pneumothorax", "Pericarditis"]', 1, 'The hyperexpanded superior segment of the left lower lobe fills the space behind the collapsed LUL.'),
    (v_topic_id, '311: "Atelectasis" of the "Left Lower Lobe" (LLL) often appears on a PA film as:', '["A triangular opacity behind the heart (the flat-waist sign)", "A large mass", "A wide mediastinum", "Tracheal deviation to the right"]', 0, 'The LLL collapses medially and posteriorly.'),
    (v_topic_id, '312: Which of the following can cause "Mediastinal Shift" TOWARD the side of the abnormality?', '["Large pleural effusion", "Total lung collapse (e.g., from an obstructing mucus plug)", "Tension pneumothorax", "Large lung tumor"]', 1, 'Total collapse creates a vacuum that pulls the mediastinum.'),
    (v_topic_id, '313: Which of the following can cause "Mediastinal Shift" AWAY from the side of the abnormality?', '["Atelectasis", "Massive pleural effusion", "Lung fibrosis", "Pneumonectomy"]', 1, 'The large volume of fluid pushes the mobile structures to the opposite side.'),
    (v_topic_id, '314: "Drowning" or "Near-drowning" typically shows which radiographic pattern?', '["Normal CXR for 48 hours", "Rapid onset of diffuse pulmonary edema (within minutes to hours)", "Lobar pneumonia", "Pneumothorax"]', 1, 'Fluid aspiration and surfactant wash-out lead to rapid alveolar filling.'),
    (v_topic_id, '315: "Pneumoconiosis" refers to a group of lung diseases caused by:', '["Infection", "Inhalation of inorganic dusts", "Smoking", "Autoimmune disease"]', 1, 'Examples include silicosis, asbestosis, and coal worker''s lung.'),
    (v_topic_id, '316: "Hypersensitivity Pneumonitis" (Farmer''s Lung) is caused by:', '["Inhalation of organic dusts (e.g., moldy hay)", "Silica", "Bacteria", "Asbestos"]', 0, 'This is an immune-mediated reaction to inhaled organic antigens.'),
    (v_topic_id, '317: A "Snowman" heart (or Figure-of-8) is a classic radiographic sign of:', '["Tetralogy of Fallot", "Total Anomalous Pulmonary Venous Return (Supracardiac)", "Coarctation of the aorta", "Patent ductus arteriosus"]', 1, 'The "head" of the snowman is formed by a dilated vertical vein and the SVC.'),
    (v_topic_id, '318: "Coarctation of the aorta" often causes "Rib Notching." Which ribs are typically spared?', '["1st and 2nd ribs (because they are supplied by the costocervical trunk)", "4th and 5th ribs", "9th and 10th ribs", "All ribs are notched"]', 0, 'The notching occurs where the intercostal arteries act as collaterals to bypass the coarctation.'),
    (v_topic_id, '319: "Osteolytic" bone metastases (holes in the bone) are common in which cancer?', '["Prostate cancer", "Breast and Lung cancer", "Thyroid cancer", "Stomach cancer"]', 1, 'Breast cancer can be both lytic and blastic.'),
    (v_topic_id, '320: "Osteoblastic" bone metastases (dense white spots) are most classic for:', '["Lung cancer", "Prostate cancer", "Myeloma", "Colon cancer"]', 1, 'Prostate cancer characteristically stimulates bone formation.'),
    (v_topic_id, '321: "Multiple Myeloma" is characteristically "Cold" on which imaging modality?', '["CT", "X-ray", "Technetium-99m Bone Scan", "MRI"]', 2, 'Bone scans detect osteoblastic activity; since myeloma is purely lytic, the scan may be falsely negative.'),
    (v_topic_id, '322: The "FAST" exam (Focused Assessment with Sonography for Trauma) evaluates for:', '["Pneumonia", "Free fluid (hemoperitoneum) in the peritoneal and pericardial spaces", "Rib fractures", "Lung cancer"]', 1, 'It is a rapid bedside test used in the ER for trauma patients.'),
    (v_topic_id, '323: The four standard views of a FAST exam are:', '["Morison''s pouch (RUQ), Splenorenal recess (LUQ), Suprapubic (Pelvis), and Subxiphoid (Pericardium)", "Lungs, Heart, Liver, Brain", "Neck, Chest, Abdomen, Pelvis", "Arms and Legs"]', 0, 'These are the most common areas for free fluid to pool.'),
    (v_topic_id, '324: "Morison''s Pouch" is the potential space between the:', '["Liver and right kidney", "Spleen and left kidney", "Bladder and rectum", "Stomach and diaphragm"]', 0, 'This is the most sensitive site for detecting free fluid in the supine patient.'),
    (v_topic_id, '325: An "extended FAST" (eFAST) adds which evaluation to the standard FAST?', '["Brain", "Lung (to look for pneumothorax)", "Kidneys", "Aorta"]', 1, 'Ultrasound is highly sensitive for pneumothorax (looking for the "lung sliding" sign).'),
    (v_topic_id, '326: The "Lung Sliding" sign on Ultrasound proves:', '["The patient is dead", "The visceral and parietal pleura are in contact (rules out pneumothorax at that location)", "The patient has pneumonia", "There is a pleural effusion"]', 1, 'Absence of sliding suggests a pneumothorax.'),
    (v_topic_id, '327: "Bar Code" or "Stratosphere" sign on M-mode Ultrasound indicates:', '["Normal lung", "Pneumothorax", "Pleural effusion", "Pneumonia"]', 1, 'The lack of movement creates parallel horizontal lines.'),
    (v_topic_id, '328: "Seashore" sign on M-mode Ultrasound indicates:', '["Normal lung", "Pneumothorax", "Pulmonary edema", "Rib fracture"]', 0, 'The moving lung creates a "sandy" appearance below the pleural line.'),
    (v_topic_id, '329: "Comet Tail" artifacts (B-lines) on Lung Ultrasound are a sign of:', '["Normal lung", "Interstitial syndrome (e.g., pulmonary edema or fibrosis)", "Pneumothorax", "Normal rib"]', 1, 'They are the ultrasound equivalent of Kerley B lines.'),
    (v_topic_id, '330: Which "contrast agent" is used in Ultrasound to improve visualization of blood flow?', '["Iodine", "Barium", "Microbubbles", "Gadolinium"]', 2, 'Tiny bubbles of gas reflect the sound waves.'),
    (v_topic_id, '331: "Intussusception" (one segment of bowel sliding into another) in a child classically shows a _____ sign on Ultrasound.', '["Target or Donut", "Coffee bean", "String", "Crescent"]', 0, 'This represents the layers of the bowel wall seen in cross-section.'),
    (v_topic_id, '332: "Target sign" on a CT of the abdomen in a patient with RLQ pain is classic for:', '["Appendicitis", "Gallstones", "Renal colic", "Colitis"]', 0, 'The distended, thick-walled appendix looks like a target.'),
    (v_topic_id, '333: "Pyloric Stenosis" in an infant is best diagnosed with:', '["Abdominal X-ray", "Ultrasound (measuring muscle thickness)", "CT scan", "MRI"]', 1, 'Ultrasound is safe and highly accurate for this condition.'),
    (v_topic_id, '334: "Renal Colic" (kidney stone pain) is best evaluated with:', '["Standard KUB X-ray", "Non-contrast CT Abdomen/Pelvis (CT KUB)", "Ultrasound", "MRI"]', 1, 'Non-contrast CT is the gold standard for detecting stones of all compositions.'),
    (v_topic_id, '335: "Uric Acid" stones are unique because they are:', '["Radiopaque", "Radiolucent (invisible on plain X-ray)", "Large", "Blue"]', 1, 'They are seen on CT but not on a standard abdominal film.'),
    (v_topic_id, '336: "CT Contrast" is contraindicated in which group of patients?', '["Diabetics", "Patients with severe renal failure or prior anaphylactic reaction to iodine", "Patients with a cold", "Athletes"]', 1, 'Contrast can cause nephrotoxicity in those with pre-existing kidney disease.'),
    (v_topic_id, '337: "Metformin" should be held for 48 hours after a contrast CT to avoid:', '["Nausea", "Lactic Acidosis", "Kidney stones", "Allergy"]', 1, 'If the contrast causes temporary renal impairment, metformin can accumulate to toxic levels.'),
    (v_topic_id, '338: "Avascular Necrosis" (AVN) of the femoral head is best detected early by:', '["Plain X-ray", "MRI", "CT scan", "Ultrasound"]', 1, 'MRI is extremely sensitive for bone marrow edema, the earliest sign of AVN.'),
    (v_topic_id, '339: "Osteomyelitis" (bone infection) on X-ray may take how long to appear?', '["1 to 2 hours", "10 to 14 days", "1 month", "Immediately"]', 1, 'Early bone infection is often "radiographically occult" (invisible) on plain films.'),
    (v_topic_id, '340: A "Stress Fracture" is often initially invisible on X-ray but may appear later as:', '["A large gap", "A focal area of periosteal reaction or callous formation", "A tumor", "Dislocation"]', 1, 'Healing bone becomes visible after a few weeks.'),
    (v_topic_id, '341: "DEXA scan" is used to measure:', '["Heart rate", "Bone mineral density (for Osteoporosis)", "Lung volume", "Brain activity"]', 1, 'It provides a "T-score" compared to a healthy young adult.'),
    (v_topic_id, '342: A "T-score" of less than -2.5 on a DEXA scan defines:', '["Osteopenia", "Osteoporosis", "Normal bone", "Osteomalacia"]', 1, 'Scores between -1.0 and -2.5 are termed osteopenia.'),
    (v_topic_id, '343: "Lead Poisoning" in children can show which characteristic finding on a long bone X-ray?', '["Bone tumors", "Lead lines (dense white bands at the metaphyses)", "Fractures", "Wasting"]', 1, 'Lead interferes with normal bone remodeling.'),
    (v_topic_id, '344: "Rickets" (Vitamin D deficiency) in children shows which classic radiographic signs?', '["Dense bones", "Cupping and fraying of the metaphyses and widening of the growth plates", "Rib fractures", "Normal bones"]', 1, 'This is most prominent at the wrists and knees.'),
    (v_topic_id, '345: "Scurvy" (Vitamin C deficiency) can show "Pelkan spur" and "Wimberger ring." These are signs found in the:', '["Teeth", "Bones", "Lungs", "Heart"]', 1, 'These are signs of abnormal bone matrix and hemorrhage.'),
    (v_topic_id, '346: "Computed Radiography" (CR) and "Digital Radiography" (DR) have largely replaced:', '["MRI", "Traditional Film-screen radiography", "Ultrasound", "CT"]', 1, 'Digital systems allow for easier storage (PACS) and image manipulation.'),
    (v_topic_id, '347: "PACS" stands for:', '["Patient Access Computer System", "Picture Archiving and Communication System", "Public Area Control System", "Primary Anatomy Control System"]', 1, 'This is the digital library for all medical images.'),
    (v_topic_id, '348: "DICOM" is the universal:', '["X-ray machine", "File format for medical imaging", "Radiologist certification", "Contrast agent"]', 1, 'Digital Imaging and Communications in Medicine ensures all machines can "talk" to each other.'),
    (v_topic_id, '349: "ALARA" principle in radiology stands for:', '["All Lungs Are Radiopaque", "As Low As Reasonably Achievable (regarding radiation dose)", "Always Look At Ribs Always", "At Least A Right Angle"]', 1, 'Clinicians must minimize radiation exposure, especially in children and pregnant women.'),
    (v_topic_id, '350: Which of the following carries NO radiation risk?', '["CT and X-ray", "MRI and Ultrasound", "PET and Bone scans", "Fluoroscopy"]', 1, 'MRI uses magnetic fields and US uses sound waves, making them safer for repeated use.');
